eqdc &lt;- '+proj=eqdc +lat_0=40 +lon_0=-96 +lat_1=20 +lat_2=60 +x_0=0 +y_0=0 +datum=NAD83 +units=m +no_defs'

# Load all US states (excluding Puerto Rico)
states &lt;- aoi_get(state = 'all') |&gt; 
  filter(name != "Puerto Rico") |&gt;
  st_transform(crs = eqdc)

# Load country boundaries
countries &lt;- aoi_get(country = c("MX", "CA", "USA")) |&gt; 
  st_transform(crs = eqdc)

eqdc &lt;- '+proj=eqdc +lat_0=40 +lon_0=-96 +lat_1=20 +lat_2=60 +x_0=0 +y_0=0 +datum=NAD83 +units=m +no_defs'

# Load all US states (excluding Puerto Rico)
states &lt;- aoi_get(state = 'all') |&gt; 
  filter(name != "Puerto Rico") |&gt;
  st_transform(crs = eqdc)

# Load country boundaries
countries &lt;- aoi_get(country = c("MX", "CA", "USA")) |&gt; 
  st_transform(crs = eqdc)

2.

2.1

usa_border &lt;- states |&gt;
  st_union() |&gt;
  st_cast("MULTILINESTRING")

cities &lt;- cities |&gt;
  mutate(dist_to_usa_border_km = drop_units(set_units(st_distance(geometry, usa_border), "km")))

cities |&gt;
  select(city, state_name, dist_to_usa_border_km) |&gt;
  slice_max(dist_to_usa_border_km, n = 5) |&gt;
  flextable()

